using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Management;
using System.Runtime.InteropServices;
using System.Text;
public static class Local {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Auto)]class MemoryStatus {public uint Length=(uint)Marshal.SizeOf(typeof(MemoryStatus));public uint Load;public ulong TotalPhys,AvailPhys,TotalPage,AvailPage,TotalVirtual,AvailVirtual,AvailExtended;}
 [DllImport("kernel32.dll",CharSet=CharSet.Auto,SetLastError=true)]static extern bool GlobalMemoryStatusEx([In,Out]MemoryStatus data);
 public static Metrics Collect(){var m=new Metrics();try{PeripheralCollector.CollectLocal(m);}catch{}try{List<Dictionary<string,object>> rows;try{rows=Query("SELECT Name,PercentProcessorTime,ProcessorFrequency FROM Win32_PerfFormattedData_Counters_ProcessorInformation");}catch{rows=Query("SELECT Name,PercentProcessorTime FROM Win32_PerfFormattedData_Counters_ProcessorInformation");}if(rows.Count==0)rows=Query("SELECT Name,PercentProcessorTime FROM Win32_PerfFormattedData_PerfOS_Processor");var cores=new List<KeyValuePair<string,double>>();foreach(var r in rows){string name=Convert.ToString(r["Name"]);double value=Math.Max(0,Math.Min(100,Convert.ToDouble(r["PercentProcessorTime"],CultureInfo.InvariantCulture)));if(name=="_Total"){m.Cpu=value.ToString("0.0",CultureInfo.InvariantCulture)+"%";object clock;double mhz;if(r.TryGetValue("ProcessorFrequency",out clock)&&double.TryParse(Convert.ToString(clock,CultureInfo.InvariantCulture),NumberStyles.Float,CultureInfo.InvariantCulture,out mhz)&&mhz>0)m.CpuFrequencyMHz=mhz;}else if(!name.Contains("_Total"))cores.Add(new KeyValuePair<string,double>(name,value));}int index=0;foreach(var item in cores.OrderBy(x=>SortKey(x.Key)))m.CpuCores.Add(new CpuCore{Index=index++,Util=item.Value});m.Cores=m.CpuCores.Count.ToString();if(m.Cpu=="—"&&cores.Count>0)m.Cpu=cores.Average(x=>x.Value).ToString("0.0",CultureInfo.InvariantCulture)+"%";if(cores.Count==0)m.Error="Windows 未返回 CPU 性能计数器，请检查系统 WMI 服务。";}catch(Exception e){m.Error="本机 CPU 采集失败："+e.Message;}
 var memory=new MemoryStatus();if(GlobalMemoryStatusEx(memory))m.Mem=((memory.TotalPhys-memory.AvailPhys)/1048576)+" / "+(memory.TotalPhys/1048576)+" MiB";
 try{var drive=new DriveInfo(Path.GetPathRoot(Environment.SystemDirectory));m.Disk=((drive.TotalSize-drive.TotalFreeSpace)*100.0/drive.TotalSize).ToString("0")+"% used / "+(drive.TotalFreeSpace/1073741824.0).ToString("0.0")+"G free";}catch{}
 var raw=RunSmi("--query-gpu=index,name,utilization.gpu,memory.used,memory.total,temperature.gpu,fan.speed,power.draw,power.limit,uuid,power.max_limit --format=csv,noheader,nounits");foreach(var line in raw.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)){var a=line.Split(',');if(a.Length>=10)m.Gpus.Add(new Gpu{Index=a[0].Trim(),Name=a[1].Trim(),Util=a[2].Trim(),Used=a[3].Trim(),Total=a[4].Trim(),Temp=a[5].Trim(),Fan=a[6].Trim(),Power=a[7].Trim(),Cap=a[8].Trim(),Uuid=a[9].Trim(),PowerMax=a.Length>=11?a[10].Trim():null});}
 if(m.Gpus.Count>0){var clocks=RunSmi("--query-gpu=uuid,clocks.current.graphics --format=csv,noheader,nounits");foreach(var clockLine in clocks.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)){var fields=clockLine.Split(',');if(fields.Length==2){var target=m.Gpus.Find(g=>g.Uuid==fields[0].Trim());if(target!=null)target.Clock=fields[1].Trim();}}raw=RunSmi("--query-compute-apps=gpu_uuid,pid,process_name,used_gpu_memory --format=csv,noheader,nounits");foreach(var line in raw.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries)){var a=line.Split(',');if(a.Length<4)continue;string pid=a[1].Trim();var gpu=m.Gpus.Find(x=>x.Uuid==a[0].Trim());m.Processes.Add(new GpuProcess{Gpu=gpu==null?"?":gpu.Index,Pid=pid,Name=string.Join(",",a,2,a.Length-3).Trim(),Memory=a[a.Length-1].Trim()+" MiB",Type="C",User=Owner(pid)});}}LocalGpu.Enrich(m,RunSmi);ProcessMetadata.Enrich(m.Processes);m.Hardware=HardwareInventory.Get(Storage.LocalServer());return m;}
 static int SortKey(string value){var a=value.Split(',');int group=0,core=0;if(a.Length==2){int.TryParse(a[0],out group);int.TryParse(a[1],out core);}else int.TryParse(value,out core);return group*65536+core;}
 static List<Dictionary<string,object>> Query(string query){var values=new List<Dictionary<string,object>>();using(var search=new ManagementObjectSearcher("root\\CIMV2",query)){search.Options.Timeout=TimeSpan.FromSeconds(5);using(var results=search.Get())foreach(ManagementObject row in results){using(row){var data=new Dictionary<string,object>();foreach(PropertyData property in row.Properties)data[property.Name]=property.Value;values.Add(data);}}}return values;}
 static string Owner(string pid){int n;if(!int.TryParse(pid,out n))return "—";try{using(var p=new ManagementObject("Win32_Process.Handle='"+n+"'")){var args=new string[2];var result=Convert.ToUInt32(p.InvokeMethod("GetOwner",args));if(result==0)return string.IsNullOrEmpty(args[1])?args[0]:args[1]+"\\"+args[0];}}catch{}return "—";}
 static string RunSmi(string args){string exe="nvidia-smi.exe";foreach(string candidate in new[]{Path.Combine(Environment.SystemDirectory,"nvidia-smi.exe"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"NVIDIA Corporation","NVSMI","nvidia-smi.exe")})if(File.Exists(candidate)){exe=candidate;break;}try{using(var p=new Process{StartInfo=new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8}}){p.Start();var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(5000)){try{p.Kill();}catch{}return "";}return p.ExitCode==0?output.Result:"";}}catch{return "";}}
}
